func LoadHydroPilot() (*axiom.App, error) {
	module, err := axiom.Compile([]byte(HydroPilotAXMSource), axiom.WithSourceName("HydroPilot.axm"))
	if err != nil {
		return nil, err
	}
	return &axiom.App{Path: "HydroPilot.axm", Module: module}, nil
}

func NewHydroPilot(impl HydroPilotActivities, opts ...axiom.Option) (*axiom.Engine, error) {
	if impl == nil {
		return nil, axiom.Error{Code: "AX500", Kind: "config", Message: "HydroPilot activities implementation is required"}
	}
	app, err := LoadHydroPilot()
	if err != nil {
		return nil, err
	}
	registry := axiom.ActivityRegistry{
		ActivityBuildCalibrationUartRequest: adaptBuildCalibrationUartRequest(impl.BuildCalibrationUartRequest),
		ActivityBuildLightingUartRequest:    adaptBuildLightingUartRequest(impl.BuildLightingUartRequest),
		ActivityBuildMeasurementUartRequest: adaptBuildMeasurementUartRequest(impl.BuildMeasurementUartRequest),
		ActivityCalculateDosePlan:           adaptCalculateDosePlan(impl.CalculateDosePlan),
		ActivityNotifyOperator:              adaptNotifyOperator(impl.NotifyOperator),
		ActivityParseZoneMeasurement:        adaptParseZoneMeasurement(impl.ParseZoneMeasurement),
		ActivitySendUartRequest:             adaptSendUartRequest(impl.SendUartRequest),
		ActivityStoreCalibration:            adaptStoreCalibration(impl.StoreCalibration),
		ActivityStoreZoneMeasurement:        adaptStoreZoneMeasurement(impl.StoreZoneMeasurement),
	}
	all := append([]axiom.Option{axiom.WithActivities(registry)}, opts...)
	return app.New(all...)
}

